 $("#siteAppearanceForm")?.addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),payload={id:1,theme_key:THEME_KEYS.includes(fd.get("theme_key"))?fd.get("theme_key"):"field-ops",seasonal_enabled:fd.get("seasonal_enabled")==="on",updated_at:new Date().toISOString()};const {error}=await db.from("site_appearance").upsert(payload,{onConflict:"id"});if(error){msg($("#siteAppearanceStatus"),error.message||adminError(error),"error");return;}msg($("#siteAppearanceStatus"),"Website appearance saved. Refresh the public website to see the change.","success");});
