 async function uploadCampaignImage(file){
  if(!file||!file.size)return {url:""};
  if(!["image/jpeg","image/png","image/webp"].includes(file.type))return {error:"Use JPG, PNG or WEBP images."};
  if(file.size>8*1024*1024)return {error:"Image must be 8 MB or smaller."};
  const ext=({"image/jpeg":"jpg","image/png":"png","image/webp":"webp"})[file.type],path=`seasonal/${crypto.randomUUID()}.${ext}`;
  const {error}=await db.storage.from("fieldzero-gallery").upload(path,file,{contentType:file.type,upsert:false});
  if(error)return {error:error.message};
  const {data:{publicUrl}}=db.storage.from("fieldzero-gallery").getPublicUrl(path);return {url:publicUrl,path};
 }
 function campaignPayloadFromForm(form,fd){
  const title=String(fd.get("title")||"").trim(),start_date=String(fd.get("start_date")||""),end_date=String(fd.get("end_date")||"");
  if(title.length<2)return {error:"Enter a campaign title."};
  if(!start_date||!end_date)return {error:"Choose both start and end dates."};
  if(end_date<start_date)return {error:"End date must be on or after start date."};
  const days=(Date.parse(end_date+"T00:00:00Z")-Date.parse(start_date+"T00:00:00Z"))/86400000+1;
  if(days<3||days>4)return {error:"Use a 3–4 day display window. Both the start and end dates count."};
  return {payload:{title,category:String(fd.get("category")||"Seasonal"),message:String(fd.get("message")||"").trim(),image_url:String(fd.get("image_url")||"").trim()||null,alt_text:String(fd.get("alt_text")||"").trim(),start_date,end_date,theme_key:THEME_KEYS.includes(fd.get("theme_key"))?fd.get("theme_key"):"field-ops",cta_target:CTAS.includes(fd.get("cta_target"))?fd.get("cta_target"):"none",cta_label:String(fd.get("cta_label")||"").trim(),priority:Math.max(0,Math.min(1000,Number(fd.get("priority")||0))),recurs_annually:fd.get("recurs_annually")==="on",auto_theme:fd.get("auto_theme")==="on",popup_enabled:fd.get("popup_enabled")==="on",active:fd.get("active")==="on",updated_at:new Date().toISOString()}};
 }
 function campaignSlug(title){return String(title||"campaign").toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,70)||"campaign";}
 async function loadSeasonalCampaignsAdmin(){
  const el=$("#seasonalCampaignsAdmin");if(!el)return;
  const {data,error}=await db.from("seasonal_campaigns").select("id,slug,title,category,message,image_url,alt_text,start_date,end_date,recurs_annually,active,popup_enabled,auto_theme,theme_key,cta_target,cta_label,priority,updated_at").order("start_date",{ascending:true});
  if(error){el.innerHTML=`<p class="admin-error">${esc(error.message||adminError(error))} Run supabase/upgrade-v10-seasonal-theme.sql after V9.</p>`;return;}
  if(!data?.length){el.innerHTML='<div class="empty-state">No seasonal campaigns yet. Add one above or seed the suggested Sri Lankan calendar with the included migration.</div>';return;}
  el.innerHTML=data.map(c=>`<article class="season-campaign-card" data-campaign-card="${c.id}"><img src="${esc(c.image_url||"")}" alt="${esc(c.alt_text||c.title||"")}" loading="lazy" onerror="this.style.visibility='hidden'"><div class="season-campaign-content"><span class="season-window-chip">${c.recurs_annually?'REPEATS ANNUALLY': 'SCHEDULED'} · ${c.active?'ACTIVE':'PAUSED'}</span><h3>${esc(c.title)}</h3><p>${esc(c.message)}</p><div class="season-campaign-fields">
   <label class="full">Title<input data-cfield="title" value="${esc(c.title)}" maxlength="100"></label>
   <label>Category<select data-cfield="category">${categoryOptions(c.category)}</select></label><label>Start date<input type="date" data-cfield="start_date" value="${esc(c.start_date)}"></label><label>End date<input type="date" data-cfield="end_date" value="${esc(c.end_date)}"></label>
   <label class="full">Greeting text<textarea data-cfield="message" maxlength="500">${esc(c.message)}</textarea></label>
   <label class="full">Image URL<input type="url" data-cfield="image_url" value="${esc(c.image_url||"")}" placeholder="https://…"></label>
   <label class="full">Upload replacement image<input type="file" data-cfield-file accept="image/jpeg,image/png,image/webp"></label>
   <label class="full">Image description<input data-cfield="alt_text" value="${esc(c.alt_text||"")}" maxlength="180"></label>
   <label>Campaign theme<select data-cfield="theme_key">${themeOptions(c.theme_key)}</select></label><label>Button link<select data-cfield="cta_target">${ctaOptions(c.cta_target)}</select></label><label>Button label<input data-cfield="cta_label" value="${esc(c.cta_label||"")}" maxlength="40"></label><label>Priority<input type="number" data-cfield="priority" min="0" max="1000" value="${Number(c.priority||0)}"></label>
   </div><div class="season-campaign-checks"><label><input type="checkbox" data-cfield-check="recurs_annually" ${c.recurs_annually?'checked':''}> REPEAT YEARLY</label><label><input type="checkbox" data-cfield-check="auto_theme" ${c.auto_theme?'checked':''}> CHANGE THEME</label><label><input type="checkbox" data-cfield-check="popup_enabled" ${c.popup_enabled?'checked':''}> POP-UP</label><label><input type="checkbox" data-cfield-check="active" ${c.active?'checked':''}> ACTIVE</label></div><div class="season-campaign-actions"><button class="button button-lime" data-save-campaign="${c.id}">SAVE CAMPAIGN</button><button class="button button-danger" data-delete-campaign="${c.id}" data-title="${esc(c.title)}">DELETE</button></div></div></article>`).join("");
  el.querySelectorAll("[data-save-campaign]").forEach(btn=>btn.addEventListener("click",async()=>{const card=btn.closest("[data-campaign-card]"),read=k=>card.querySelector(`[data-cfield="${k}"]`),readCheck=k=>card.querySelector(`[data-cfield-check="${k}"]`),title=read("title").value.trim(),start_date=read("start_date").value,end_date=read("end_date").value;if(!title||!start_date||!end_date||end_date<start_date){msg($("#seasonalCampaignStatus"),"Enter a title and valid start/end dates.","error");return;}const days=(Date.parse(end_date+"T00:00:00Z")-Date.parse(start_date+"T00:00:00Z"))/86400000+1;if(days<3||days>4){msg($("#seasonalCampaignStatus"),"Use a 3–4 day display window. Both the start and end dates count.","error");return;}let image_url=read("image_url").value.trim()||null;const file=card.querySelector("[data-cfield-file]").files[0];if(file){const upload=await uploadCampaignImage(file);if(upload.error){msg($("#seasonalCampaignStatus"),upload.error,"error");return;}image_url=upload.url;}const payload={title,category:read("category").value,message:read("message").value.trim(),image_url,alt_text:read("alt_text").value.trim(),start_date,end_date,theme_key:read("theme_key").value,cta_target:read("cta_target").value,cta_label:read("cta_label").value.trim(),priority:Math.max(0,Math.min(1000,Number(read("priority").value||0))),recurs_annually:readCheck("recurs_annually").checked,auto_theme:readCheck("auto_theme").checked,popup_enabled:readCheck("popup_enabled").checked,active:readCheck("active").checked,updated_at:new Date().toISOString()};const {error}=await db.from("seasonal_campaigns").update(payload).eq("id",btn.dataset.saveCampaign);if(error){msg($("#seasonalCampaignStatus"),error.message||adminError(error),"error");return;}msg($("#seasonalCampaignStatus"),"Campaign saved. Its banner and popup follow the Sri Lanka date window.","success");await loadSeasonalCampaignsAdmin();}));
  el.querySelectorAll("[data-delete-campaign]").forEach(btn=>btn.addEventListener("click",async()=>{if(!confirm(`Delete the seasonal campaign “${btn.dataset.title}”? This cannot be undone.`))return;const {error}=await db.from("seasonal_campaigns").delete().eq("id",btn.dataset.deleteCampaign);if(error){msg($("#seasonalCampaignStatus"),error.message||adminError(error),"error");return;}msg($("#seasonalCampaignStatus"),"Campaign deleted.","success");await loadSeasonalCampaignsAdmin();}));
 }
 $("#seasonalCampaignForm")?.addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),built=campaignPayloadFromForm(form,fd);if(built.error){msg($("#seasonalCampaignStatus"),built.error,"error");return;}let payload=built.payload;const title=payload.title;const imageFile=fd.get("image_file");if(imageFile instanceof File&&imageFile.size){const upload=await uploadCampaignImage(imageFile);if(upload.error){msg($("#seasonalCampaignStatus"),upload.error,"error");return;}payload.image_url=upload.url;}const baseSlug=campaignSlug(title),slug=`${baseSlug}-${payload.start_date.slice(0,4)}`;const {error}=await db.from("seasonal_campaigns").insert({...payload,slug});if(error){msg($("#seasonalCampaignStatus"),error.code==="23505"?"A campaign with this title/year already exists. Edit the existing campaign below.":(error.message||adminError(error)),"error");return;}form.reset();form.elements.namedItem("theme_key").value="field-ops";form.elements.namedItem("cta_target").value="none";form.elements.namedItem("priority").value="50";msg($("#seasonalCampaignStatus"),"Seasonal campaign created. It will appear only within its scheduled dates.","success");await loadSeasonalCampaignsAdmin();});

 async function loadSessionPricesAdmin(){
  const el=$("#sessionPricesAdmin");if(!el)return;
  const {data,error}=await db.from("session_prices").select("package_key,package_name,price_amount,price_currency,display_label,price_note,active").order("package_name");
  if(error){el.innerHTML=`<p class="admin-error">${esc(error.message||adminError(error))} Apply supabase/upgrade-v9-launch-operators-pricing.sql.</p>`;return;}
  if(!data?.length){el.innerHTML='<div class="empty-state">No session price records found. Run the V9 migration.</div>';return;}
  el.innerHTML=data.map(row=>`<article class="session-price-admin-row"><div class="session-price-admin-heading"><b>${esc(row.package_name)}</b><small>${esc(row.package_key)}</small></div><label>Price amount <input type="number" min="0" max="99999999" step="0.01" placeholder="Custom / none" value="${row.price_amount===null?"":Number(row.price_amount)}" data-session-price-field="amount" data-session-price-key="${row.package_key}"></label><label>Currency <select data-session-price-field="currency" data-session-price-key="${row.package_key}"><option value="LKR" ${row.price_currency==='LKR'?'selected':''}>LKR (Rs.)</option><option value="USD" ${row.price_currency==='USD'?'selected':''}>USD ($)</option></select></label><label>Display label if no amount <input maxlength="40" value="${esc(row.display_label||"")}" placeholder="Custom / Coming soon" data-session-price-field="label" data-session-price-key="${row.package_key}"></label><label>Small note below price <input maxlength="120" value="${esc(row.price_note||"")}" placeholder="per player / quote after enquiry" data-session-price-field="note" data-session-price-key="${row.package_key}"></label><label class="admin-toggle-label session-price-active"><input type="checkbox" data-session-price-field="active" data-session-price-key="${row.package_key}" ${row.active?'checked':''}> SHOW ON PUBLIC WEBSITE</label><div class="session-price-admin-actions"><button class="button button-lime" data-save-session-price="${row.package_key}">SAVE PRICE</button></div></article>`).join("");
  el.querySelectorAll("[data-save-session-price]").forEach(btn=>btn.addEventListener("click",async()=>{const key=btn.dataset.saveSessionPrice,read=field=>el.querySelector(`[data-session-price-key="${key}"][data-session-price-field="${field}"]`),raw=read("amount").value.trim(),amount=raw===""?null:Number(raw);if(amount!==null&&(!Number.isFinite(amount)||amount<0)){msg($("#sessionPricesStatus"),"Enter a valid price or leave the amount blank for a custom price.","error");return;}const payload={price_amount:amount,price_currency:read("currency").value,display_label:read("label").value.trim()||(amount===null?"Custom":""),price_note:read("note").value.trim(),active:read("active").checked,updated_at:new Date().toISOString()};const {error}=await db.from("session_prices").update(payload).eq("package_key",key);if(error){msg($("#sessionPricesStatus"),error.message||adminError(error),"error");return;}msg($("#sessionPricesStatus"),"Session price saved. Refresh the public website to see the new price.","success");}));
 }
 async function loadGalleryAdmin(){const el=$('#galleryAdminList');if(!el)return;const {data,error}=await db.from('gallery_photos').select('id,title,session_name,image_url,storage_path,popup_featured,published,created_at').order('created_at',{ascending:false});if(error){el.innerHTML=`<p class="admin-error">${esc(adminError(error))} Apply supabase/upgrade-v7-gallery.sql.</p>`;return}if(!data?.length){el.innerHTML='<div class="empty-state">No gallery photos uploaded yet.</div>';return}el.innerHTML=data.map(photo=>`<article class="gallery-admin-card"><img src="${esc(photo.image_url)}" alt=""><div><h3>${esc(photo.title||'FIELD MOMENT')}</h3><p>${esc(photo.session_name||'FIELDZERO SESSION')} · ${photo.popup_featured?'FEATURED POP-UP':'STANDARD PHOTO'} · ${photo.published?'PUBLISHED':'HIDDEN'}</p><div class="gallery-admin-actions"><button class="button button-ghost" data-gallery-feature="${photo.id}" data-featured="${photo.popup_featured}">${photo.popup_featured?'REMOVE POP-UP':'FEATURE POP-UP'}</button><button class="button button-ghost" data-gallery-publish="${photo.id}" data-published="${photo.published}">${photo.published?'HIDE PHOTO':'PUBLISH PHOTO'}</button><button class="button button-danger" data-gallery-delete="${photo.id}" data-path="${esc(photo.storage_path)}" data-title="${esc(photo.title||'photo')}">DELETE PHOTO</button></div></div></article>`).join('');el.querySelectorAll('[data-gallery-feature]').forEach(btn=>btn.addEventListener('click',async()=>{const {error}=await db.from('gallery_photos').update({popup_featured:btn.dataset.featured!=='true'}).eq('id',btn.dataset.galleryFeature);if(error){msg($('#galleryAdminStatus'),adminError(error),'error');return}msg($('#galleryAdminStatus'),'Featured pop-up setting updated.','success');await loadGalleryAdmin()}));el.querySelectorAll('[data-gallery-publish]').forEach(btn=>btn.addEventListener('click',async()=>{const {error}=await db.from('gallery_photos').update({published:btn.dataset.published!=='true'}).eq('id',btn.dataset.galleryPublish);if(error){msg($('#galleryAdminStatus'),adminError(error),'error');return}msg($('#galleryAdminStatus'),'Photo visibility updated.','success');await loadGalleryAdmin()}));el.querySelectorAll('[data-gallery-delete]').forEach(btn=>btn.addEventListener('click',async()=>{if(!confirm(`Permanently delete ${btn.dataset.title} from the gallery?`))return;const path=btn.dataset.path;const removed=await db.storage.from('fieldzero-gallery').remove([path]);if(removed.error){msg($('#galleryAdminStatus'),'Photo file could not be deleted: '+removed.error.message,'error');return}const {error}=await db.from('gallery_photos').delete().eq('id',btn.dataset.galleryDelete);if(error){msg($('#galleryAdminStatus'),adminError(error),'error');return}msg($('#galleryAdminStatus'),'Photo deleted.','success');await loadGalleryAdmin()}))}
 $('#galleryUploadForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),files=Array.from(fd.getAll('photos')).filter(f=>f instanceof File&&f.size>0),session_name=String(fd.get('session_name')||'').trim(),title=String(fd.get('title')||'').trim(),popup_featured=fd.get('popup_featured')==='on',button=$('#galleryUploadButton');if(!files.length){msg($('#galleryAdminStatus'),'Choose at least one image.','error');return}if(files.some(f=>!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type))){msg($('#galleryAdminStatus'),'Use JPG, PNG, WEBP or GIF image files only.','error');return}if(files.some(f=>f.size>8*1024*1024)){msg($('#galleryAdminStatus'),'Each image must be 8 MB or smaller.','error');return}button.disabled=true;let uploaded=0;for(const file of files){const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path=`sessions/${crypto.randomUUID()}.${ext}`;const {error:uploadError}=await db.storage.from('fieldzero-gallery').upload(path,file,{contentType:file.type,upsert:false});if(uploadError){msg($('#galleryAdminStatus'),`Upload stopped after ${uploaded} photo(s): ${uploadError.message}`,'error');button.disabled=false;return}const {data:{publicUrl}}=db.storage.from('fieldzero-gallery').getPublicUrl(path);const {error:rowError}=await db.from('gallery_photos').insert({title:title||(file.name.replace(/\.[^.]+$/,'').slice(0,100)),session_name,image_url:publicUrl,storage_path:path,popup_featured:popup_featured&&uploaded===0,published:true});if(rowError){msg($('#galleryAdminStatus'),`Photo file uploaded but its gallery record failed: ${adminError(rowError)} Delete the unused file from Supabase Storage if needed.`,'error');button.disabled=false;return}uploaded++}button.disabled=false;form.reset();msg($('#galleryAdminStatus'),`${uploaded} photo(s) uploaded and published.`, 'success');await loadGalleryAdmin()});

 $("#eventForm").addEventListener("submit",async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const payload={title:String(fd.get("title")).trim(),event_type:fd.get("event_type"),event_date:fd.get("event_date")||null,start_time:fd.get("start_time")||null,end_time:fd.get("end_time")||null,location:String(fd.get("location")||"").trim(),field_id:fd.get("field_id")||null,price_amount:Number(fd.get("price_amount")||0),price_currency:fd.get("price_currency")||"LKR",description:String(fd.get("description")||"").trim(),rules:String(fd.get("rules")||"").trim(),registration_limit:fd.get("registration_limit")?Number(fd.get("registration_limit")):null,registration_deadline:fd.get("registration_deadline")||null,popup_featured:fd.get("popup_featured")==="on"};const {error}=await db.from("events").insert(payload);if(error){msg($("#adminStatus"),adminError(error),"error");return}e.currentTarget.reset();msg($("#adminStatus"),payload.popup_featured?"Event published. Its announcement will be shown on the public website when visitors open it.":"Event published on the public site.","success");await Promise.all([loadEvents(),loadResultOptions(),loadFieldsAdmin()])});
 $("#assignmentForm").addEventListener("submit",async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),player_id=fd.get("player_id"),team_id=fd.get("team_id");const existing=await db.from('team_members').select('id,active').eq('player_id',player_id).eq('team_id',team_id).maybeSingle();let error=existing.error;if(!error&&existing.data){if(existing.data.active){msg($('#assignmentStatus'),'This player is already active in that squad.','error');return}const result=await db.from('team_members').update({active:true}).eq('id',existing.data.id);error=result.error}else if(!error){const result=await db.from('team_members').insert({player_id,team_id,active:true});error=result.error}if(error){msg($("#assignmentStatus"),error.message?.includes("no more than five")?"This squad already has five active players.":error.code==="23505"?"This player is already assigned to another squad.":adminError(error),"error");return}msg($("#assignmentStatus"),"Player assigned to squad.","success");await Promise.all([loadTeams(),loadAssignmentOptions()])});
